class Solution {
public:
    int countBalls(int lowLimit, int highLimit) {
        // maximum possible digit sum for numbers up to 100000 is 45,
        // we allocate a little more to be safe.
        int cnt[100] = {0};
        int maxCnt = 0;
        for (int x = lowLimit; x <= highLimit; ++x) {
            int s = 0, y = x;
            while (y > 0) {
                s += y % 10;
                y /= 10;
            }
            ++cnt[s];
            if (cnt[s] > maxCnt) maxCnt = cnt[s];
        }
        return maxCnt;
    }
};

