/**
 * @param {number} lowLimit
 * @param {number} highLimit
 * @return {number}
 */
var countBalls = function(lowLimit, highLimit) {
    // maximum possible digit sum for numbers up to 100000 is 45,
    // we allocate a little more to be safe.
    const cnt = new Array(100).fill(0);
    let maxCnt = 0;
    for (let x = lowLimit; x <= highLimit; ++x) {
        let s = 0, y = x;
        while (y > 0) {
            s += y % 10;
            y = Math.floor(y / 10);
        }
        ++cnt[s];
        if (cnt[s] > maxCnt) maxCnt = cnt[s];
    }
    return maxCnt;
};
